  await page.getByRole("button", { name: "Calculate change" }).click();
  await expect(page.locator(".results")).toContainText("1 1-euro coin, 1 50-cent coin, 1 10-cent coin, 1 5-cent coin, 1 2-cent coin");
  await page.getByLabel("Amount owed, amount paid").fill("2.12,3.00\n2.00,1.00");
  await page.getByRole("button", { name: "Calculate change" }).click();
  await expect(page.getByRole("alert")).toContainText("Line 2: Amount paid is less than amount owed.");
  await expect(page.getByRole("button", { name: "Download .txt" })).toBeDisabled();
});

test("network failure is visible and a later request can recover", async ({ page }) => {
