import { useRef } from "react";
import type { KeyboardEvent } from "react";
import { amountText } from "../entry";
import type { AmountField, Amounts, EntryKey } from "../entry";

interface Props {
  amounts: Amounts;
  active: AmountField;
  currency: string;
  busy: boolean;
  onActive: (field: AmountField) => void;
  onKey: (key: EntryKey, replace?: boolean) => void;
  onPaste: (field: AmountField, text: string) => void;
}

export function RegisterEntry({
  amounts,
  active,
  currency,
  busy,
  onActive,
  onKey,
  onPaste,
}: Props) {
  const owedInput = useRef<HTMLInputElement>(null);
  const paidInput = useRef<HTMLInputElement>(null);

  function keyboard(event: KeyboardEvent<HTMLInputElement>) {
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    let key: EntryKey | undefined;
    if (/^\d$/.test(event.key)) key = event.key as EntryKey;
    else if (event.key === "Backspace") key = "backspace";
    else if (event.key === "Delete" || event.key === "Escape") key = "clear";
    if (key !== undefined) {
      event.preventDefault();
      const input = event.currentTarget;
      const allSelected =
        input.selectionStart === 0 && input.selectionEnd === input.value.length;
      onKey(allSelected && key === "backspace" ? "clear" : key, allSelected);
      requestAnimationFrame(() =>
        input.setSelectionRange(input.value.length, input.value.length),
      );
    } else if (event.key === "Enter" && active === "owed") {
      event.preventDefault();
      paidInput.current?.focus();
    }
  }

  return (
    <>
      <div className="amounts">
        {(["owed", "paid"] as const).map((field) => (
          <div
            className={`amount-field ${active === field ? "is-active" : ""}`}
            key={field}
          >
            <label htmlFor={`amount-${field}`}>
              <span className="display-led" aria-hidden="true" />
              Amount {field}
              <span className="display-currency">{currency}</span>
            </label>
            <input
              ref={field === "owed" ? owedInput : paidInput}
              id={`amount-${field}`}
              readOnly
              inputMode="none"
              value={amountText(amounts[field])}
              data-long={amountText(amounts[field]).length > 8}
              aria-describedby="keypad-help"
              disabled={busy}
              onFocus={() => onActive(field)}
              onKeyDown={keyboard}
              onPaste={(event) => {
                event.preventDefault();
                onPaste(field, event.clipboardData.getData("text"));
              }}
            />
          </div>
        ))}
      </div>
      <div className="entry-guide">
        <p id="keypad-help">
          Enter cents: <kbd>213</kbd> becomes <strong>2.13</strong>. Use the
          keypad or your keyboard.
        </p>
        <span className="active-label">Entering {active}</span>
      </div>
      <div className="keypad" role="group" aria-label="Money keypad">
        {["7", "8", "9", "4", "5", "6", "1", "2", "3", "0", "00"].map(
          (digit) => (
            <button
              key={digit}
              type="button"
              className="key numeric-key"
              onClick={() => onKey(digit as EntryKey)}
              aria-label={digit}
            >
              {digit}
            </button>
          ),
        )}
        <button
          type="button"
          className="key backspace-key"
          aria-label="Backspace"
          onClick={() => onKey("backspace")}
        >
          <span aria-hidden="true">⌫</span>
          <span className="key-subtitle">BACKSPACE</span>
        </button>
        <button
          type="button"
          className="key clear-key"
          aria-label="Clear active amount"
          onClick={() => onKey("clear")}
        >
          C<span className="key-subtitle">CLEAR {active.toUpperCase()}</span>
        </button>
        <button
          type="button"
          className="key field-key"
          onClick={() =>
            (active === "owed" ? paidInput : owedInput).current?.focus()
          }
        >
          {active === "owed" ? "Amount paid" : "Amount owed"}
          <span aria-hidden="true">→</span>
        </button>
      </div>
    </>
  );
}
import { useRef, useState } from "react";
import type { FormEvent, KeyboardEvent } from "react";
import { MAX_INPUT_BYTES } from "../src/limits.js";
import { amountText, enterCents, pastedCents } from "./entry";
import type { AmountField, Amounts, EntryKey } from "./entry";
import { RegisterEntry } from "./components/RegisterEntry";
import { BatchEntry } from "./components/BatchEntry";
import { Receipt } from "./components/Receipt";
import type { ReceiptData } from "./components/Receipt";
import { useRegisterSound } from "./useRegisterSound";

type Mode = "register" | "batch";
const SAMPLE = "2.12,3.00\n1.97,2.00\n3.33,5.00";

export function App() {
  const [mode, setMode] = useState<Mode>("register");
  const [amounts, setAmounts] = useState<Amounts>({ owed: 0, paid: 0 });
  const [active, setActive] = useState<AmountField>("owed");
  const [input, setInput] = useState(SAMPLE);
  const [fileName, setFileName] = useState("");
  const [currency, setCurrency] = useState("USD");
  const [divisor, setDivisor] = useState("3");
  const [receipt, setReceipt] = useState<ReceiptData | null>(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [loadingFile, setLoadingFile] = useState(false);
  const revision = useRef(0);
  const registerTab = useRef<HTMLButtonElement>(null);
  const batchTab = useRef<HTMLButtonElement>(null);
  const sound = useRegisterSound();
  const locked = busy || loadingFile;

  function changed() {
    revision.current++;
    setReceipt(null);
    setError("");
  }

  function edit(key: EntryKey, replace = false) {
    if (locked) return;
    changed();
    try {
      const next = enterCents(replace ? 0 : amounts[active], key);
      setAmounts({ ...amounts, [active]: next });
      sound.play("key");
    } catch (failure) {
      setError(
        failure instanceof Error ? failure.message : "Unable to enter amount.",
      );
    }
  }

  function paste(field: AmountField, text: string) {
    if (locked) return;
    changed();
    try {
      setAmounts({ ...amounts, [field]: pastedCents(text) });
      sound.play("key");
    } catch (failure) {
      setError(
        failure instanceof Error ? failure.message : "Unable to paste amount.",
      );
    }
  }

  function selectMode(next: Mode) {
    if (locked || mode === next) return;
    changed();
    setMode(next);
    sound.play("key");
  }

  function tabKeyboard(event: KeyboardEvent<HTMLButtonElement>) {
    let next: Mode;
    if (event.key === "Home") next = "register";
    else if (event.key === "End") next = "batch";
    else if (event.key === "ArrowLeft" || event.key === "ArrowRight")
      next = mode === "register" ? "batch" : "register";
    else return;
    event.preventDefault();
    selectMode(next);
    (next === "register" ? registerTab : batchTab).current?.focus();
  }

  async function loadFile(file: File | undefined) {
    if (!file || locked) return;
    changed();
    const current = revision.current;
    if (file.size > MAX_INPUT_BYTES) {
      setError("Choose a file no larger than 1 MiB.");
      return;
    }
    setLoadingFile(true);
    try {
      const text = new TextDecoder("utf-8", { fatal: true }).decode(
        await file.arrayBuffer(),
      );
      if (current !== revision.current) return;
      setInput(text);
      setFileName(file.name);
    } catch {
      if (current === revision.current)
        setError("This file could not be read as UTF-8 text.");
    } finally {
      setLoadingFile(false);
    }
  }

  async function calculate(event: FormEvent) {
    event.preventDefault();
    if (locked) return;
    changed();
    sound.play("key");
    const number = Number(divisor);
    if (
      !/^[0-9]+$/.test(divisor) ||
      !Number.isSafeInteger(number) ||
      number < 1
    ) {
      setError(
        "Enter a positive whole number for the random divisor in Settings.",
      );
      return;
    }
    const requestInput =
      mode === "register"
        ? `${amountText(amounts.owed)},${amountText(amounts.paid)}`
        : input;
    if (new TextEncoder().encode(requestInput).byteLength > MAX_INPUT_BYTES) {
      setError("Input must be no larger than 1 MiB.");
      return;
    }
    const current = revision.current;
    const snapshot = {
      mode,
      currency,
      divisor: number,
      amounts: mode === "register" ? { ...amounts } : null,
      sequence: current,
    };
    setBusy(true);
    try {
      const response = await fetch("/api/change", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          input: requestInput,
          currency,
          divisor: number,
        }),
        signal: AbortSignal.timeout(15_000),
      });
      const data: unknown = await response.json();
      if (current !== revision.current) return;
      if (typeof data !== "object" || data === null)
        throw new Error("Unexpected server response.");
      if (!response.ok)
        throw new Error(
          "error" in data && typeof data.error === "string"
            ? data.error
            : "Unable to calculate change.",
        );
      if (!("output" in data) || typeof data.output !== "string")
        throw new Error("Unexpected server response.");
      setReceipt({ ...snapshot, output: data.output });
      sound.play("success");
    } catch (failure) {
      if (current === revision.current)
        setError(
          failure instanceof Error
            ? failure.message
            : "Unable to reach the server.",
        );
    } finally {
      setBusy(false);
    }
  }

  function download() {
    if (!receipt) return;
    const url = URL.createObjectURL(
      new Blob([receipt.output], { type: "text/plain;charset=utf-8" }),
    );
    const link = document.createElement("a");
    link.href = url;
    link.download = "change.txt";
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  return (
    <>
      <header className="toolbar">
        <div className="toolbar-inner">
          <div className="brand">
            <span className="brand-mark" aria-hidden="true">
              ¢
            </span>
            <div>
              <h1>Cash Register</h1>
              <p>CREATIVE CASH DRAW SOLUTIONS</p>
            </div>
          </div>
          <div className="toolbar-controls">
