import { assertCents, MAX_CENTS, parseMoney } from "../src/money.js";

export type AmountField = "owed" | "paid";
export type Amounts = Readonly<Record<AmountField, number>>;
export type EntryKey = "clear" | "backspace" | "00" | `${number}`;

export function amountText(cents: number): string {
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, "0")}`;
}

export function enterCents(current: number, key: EntryKey): number {
  if (key === "clear") return 0;
  if (key === "backspace") return Math.floor(current / 10);
  if (!/^\d{1,2}$/.test(key)) throw new Error("Use digit keys to enter cents.");
  const next = current * 10 ** key.length + Number(key);
  if (next > MAX_CENTS)
    throw new Error(
      "Maximum amount is 10000000.00. The last entry was not applied.",
    );
  assertCents(next);
  return next;
}

export function pastedCents(text: string): number {
  const value = text.trim();
  if (value.includes(".")) return parseMoney(value);
  if (!/^\d+$/.test(value))
    throw new Error("Paste digits for cents, or an amount such as 2.13.");
  const cents = BigInt(value);
  if (cents > BigInt(MAX_CENTS))
    throw new Error(
      "Maximum amount is 10000000.00. The paste was not applied.",
    );
  return Number(cents);
}
import { amountText } from "../entry";
import type { Amounts } from "../entry";

export interface ReceiptData {
  readonly output: string;
  readonly mode: "register" | "batch";
  readonly currency: string;
  readonly divisor: number;
  readonly amounts: Amounts | null;
  readonly sequence: number;
}

interface Props {
  receipt: ReceiptData | null;
  busy: boolean;
  error: boolean;
  onDownload: () => void;
}

export function Receipt({ receipt, busy, error, onDownload }: Props) {
  const results = receipt?.output ? receipt.output.trimEnd().split("\n") : [];
  const status = busy
    ? "Processing transaction"
    : error
      ? "Check your entry"
      : receipt
        ? `${results.length} ${results.length === 1 ? "transaction" : "transactions"} processed`
        : "Ready for a transaction";
  return (
    <section
      className="receipt-column"
      aria-labelledby="receipt-title"
      aria-busy={busy}
    >
      <div className="section-heading">
        <h2 id="receipt-title">Your receipt</h2>
        <span
          className={`status ${receipt ? "status-success" : ""}`}
          role="status"
        >
          <span aria-hidden="true" />
          {status}
        </span>
      </div>
      <div className="receipt-stage">
        <div
          className={`receipt-paper ${receipt ? "is-printed" : ""}`}
          key={receipt?.sequence ?? "empty"}
        >
          <div className="receipt-brand">
            <span className="receipt-monogram" aria-hidden="true">
              CC
            </span>
            <strong>CREATIVE CASH DRAW</strong>
            <span>CHANGE, ACCOUNTED FOR.</span>
          </div>
          <div className="receipt-rule" />
          {!receipt ? (
            <div className="receipt-empty">
              <span className="paper-label">
                {busy
                  ? "CALCULATING…"
                  : error
                    ? "TRANSACTION ON HOLD"
                    : "AWAITING TRANSACTION"}
              </span>
              <p>
                {error
                  ? "Correct the entry to continue."
                  : "Enter the amount owed and paid, then calculate your change."}
              </p>
              <div className="receipt-placeholder" aria-hidden="true">
                <i />
                <i />
                <i />
              </div>
              <p className="paper-small">
                Your exact denomination breakdown
                <br />
                will be printed here.
              </p>
            </div>
          ) : (
            <>
              <div className="receipt-meta">
                <span>
                  {receipt.mode === "register"
                    ? "COUNTER TRANSACTION"
                    : "BATCH TRANSACTIONS"}
                </span>
                <span>{receipt.currency}</span>
              </div>
              {receipt.amounts && (
                <>
                  <dl className="receipt-amounts">
                    <div>
                      <dt>Amount owed</dt>
                      <dd>{amountText(receipt.amounts.owed)}</dd>
                    </div>
                    <div>
                      <dt>Amount paid</dt>
                      <dd>{amountText(receipt.amounts.paid)}</dd>
                    </div>
                  </dl>
                  <div className="receipt-total">
                    <span>CHANGE DUE</span>
                    <strong>
                      {amountText(receipt.amounts.paid - receipt.amounts.owed)}
                    </strong>
                  </div>
                </>
              )}
              <p className="paper-label breakdown-label">
                DENOMINATIONS TO RETURN
              </p>
              {results.length === 0 ? (
                <p className="empty-batch">No transactions in this file.</p>
