import { test } from "node:test";
import assert from "node:assert/strict";
import type { AddressInfo } from "node:net";
import { readConfig } from "../src/config.js";
import { createServiceRuntime } from "../src/runtime.js";

test("shutdown drains active work before closing adapters, and repeated stop is harmless", async (t) => {
  const events: string[] = [];
  let release!: () => void;
  let entered!: () => void;
  const started = new Promise<void>((resolve) => { entered = resolve; });
  const gate = new Promise<void>((resolve) => { release = resolve; });
  const runtime = createServiceRuntime(readConfig({}), {
    service: { async calculate() { entered(); await gate; events.push("calculated"); return { output: "No change due\n" }; } },
    async dispose() { events.push("disposed"); },
  });
  await new Promise<void>((resolve) => runtime.server.listen(0, "[REDACTED: local endpoint]", resolve));
  t.after(() => { runtime.server.closeAllConnections(); runtime.server.close(); });
  const port = (runtime.server.address() as AddressInfo).port;
  const pending = fetch(`[REDACTED: local endpoint]:${port}/api/change`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ input: "1.00,1.00" }) });
  await started;
  const stopping = runtime.stop();
  assert.equal(runtime.stop(), stopping);
  assert.equal(runtime.server.listening, false);
  assert.deepEqual(events, []);
  release();
